CREATE OR REPLACE FUNCTION public.next_voucher_code(p_type text)
 RETURNS text
 LANGUAGE plpgsql
AS $function$
DECLARE n BIGINT;
BEGIN
  IF p_type = 'thu' THEN
    n := nextval('voucher_seq_thu');
    RETURN 'PT' || LPAD(n::text, 6, '0');
  ELSIF p_type = 'chi' THEN
    n := nextval('voucher_seq_chi');
    RETURN 'PC' || LPAD(n::text, 6, '0');
  ELSE
    RAISE EXCEPTION 'invalid voucher type: %', p_type;
  END IF;
END$function$

CREATE OR REPLACE FUNCTION public.recalc_customer_debt(p_customer_id text)
 RETURNS numeric
 LANGUAGE plpgsql
AS $function$
DECLARE
  v_total_buy       NUMERIC := 0;
  v_total_paid      NUMERIC := 0;
  v_total_paid_back NUMERIC := 0;
  v_adjustment      NUMERIC := 0;
  v_new_debt        NUMERIC;
BEGIN
  SELECT COALESCE(SUM(total), 0) INTO v_total_buy
    FROM orders WHERE customer_id = p_customer_id AND status = 'completed';

  SELECT COALESCE(SUM(amount), 0) INTO v_total_paid
    FROM cash_vouchers
   WHERE payer_customer_id = p_customer_id AND type = 'thu' AND status <> 'cancelled';

  SELECT COALESCE(SUM(amount), 0) INTO v_total_paid_back
    FROM cash_vouchers
   WHERE receiver_customer_id = p_customer_id AND type = 'chi' AND status <> 'cancelled';

  SELECT COALESCE(debt_adjustment, 0) INTO v_adjustment
    FROM customers WHERE id = p_customer_id;

  v_new_debt := v_total_buy - v_total_paid + v_total_paid_back + v_adjustment;

  UPDATE customers SET debt = v_new_debt WHERE id = p_customer_id;
  RETURN v_new_debt;
END$function$
